module golden_circle (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [4:0] n,\n    input wire [8:0] k,\n    input wire [7:0] a,\n    input wire [7:0] b,\n    output reg [11:0] min_stops,\n    output reg [11:0] max_stops,\n    output reg done\n);\n\n    localparam DATA_WIDTH = 12;\n    localparam N_WIDTH = 5;\n    localparam K_WIDTH = 9;\n    localparam A_WIDTH = 8;\n    localparam B_WIDTH = 8;\n\n    localparam [2:0] IDLE          = 3'd0;\n    localparam [2:0] CALC_L        = 3'd1;\n    localparam [2:0] COMPUTE_GCD   = 3'd2;\n    localparam [2:0] COMPUTE_STOPS = 3'd3;\n    localparam [2:0] UPDATE_MIN_MAX= 3'd4;\n    localparam [2:0] NEXT_COMBO    = 3'd5;\n    localparam [2:0] NEXT_I        = 3'd6;\n    localparam [2:0] DONE_STATE    = 3'd7;\n\n    reg [2:0] state;\n    reg [DATA_WIDTH-1:0] nk_reg;\n    reg [N_WIDTH-1:0] i_reg;\n    reg [1:0] combo_reg;\n    reg [DATA_WIDTH-1:0] l_reg;\n    reg [DATA_WIDTH-1:0] min_reg, max_reg;\n    reg [DATA_WIDTH-1:0] stops_temp;\n    reg gcd_start;\n    reg gcd_done_flag;\n    reg [DATA_WIDTH-1:0] gcd_result_reg;\n\n    localparam [1:0] GCD_IDLE   = 2'd0;\n    localparam [1:0] GCD_MOD    = 2'd1;\n    localparam [1:0] GCD_UPDATE = 2'd2;\n\n    reg [1:0] gcd_state;\n    reg [DATA_WIDTH-1:0] gcd_a, gcd_b, gcd_rem;\n    wire [DATA_WIDTH-1:0] gcd_result = (l_reg == 12'd0) ? nk_reg : gcd_result_reg;\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            gcd_state <= GCD_IDLE;\n            gcd_result_reg <= 12'd0;\n            gcd_done_flag <= 1'b0;\n            gcd_rem <= 12'd0;\n            gcd_a <= 12'd0;\n            gcd_b <= 12'd0;\n        end else begin\n            case (gcd_state)\n                GCD_IDLE: begin\n                    gcd_done_flag <= 1'b0;\n                    if (gcd_start) begin\n                        gcd_a <= nk_reg;\n                        gcd_b <= l_reg;\n                        if (l_reg != 12'd0) gcd_state <= GCD_MOD;\n                        else gcd_done_flag <= 1'b1;\n                    end\n                end\n                GCD_MOD: begin\n                    gcd_rem <= gcd_a % gcd_b;\n                    gcd_state <= GCD_UPDATE;\n                end\n                GCD_UPDATE: begin\n                    gcd_a <= gcd_b;\n                    gcd_b <= gcd_rem;\n                    if (gcd_rem == 12'd0) begin\n                        gcd_result_reg <= gcd_a;\n                        gcd_done_flag <= 1'b1;\n                        gcd_state <= GCD_IDLE;\n                    end else begin\n                        gcd_state <= GCD_MOD;\n                    end\n                end\n                default: gcd_state <= GCD_IDLE;\n            endcase\n        end\n    end\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            min_stops <= 12'd0;\n            max_stops <= 12'd0;\n            nk_reg <= 12'd0;\n            i_reg <= 5'd0;\n            combo_reg <= 2'd0;\n            l_reg <= 12'd0;\n            min_reg <= {DATA_WIDTH{1'b1}};\n            max_reg <= 12'd0;\n            gcd_start <= 1'b0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        nk_reg <= n * k;\n                        i_reg <= 5'd0;\n                        combo_reg <= 2'd0;\n                        min_reg <= {DATA_WIDTH{1'b1}};\n                        max_reg <= 12'd0;\n                        state <= CALC_L;\n                    end\n                end\n\n                CALC_L: begin\n                    case (combo_reg)\n                        2'd0: l_reg <= (i_reg * k + b - a) % nk_reg;\n                        2'd1: l_reg <= (i_reg * k + nk_reg - b - a) % nk_reg;\n                        2'd2: l_reg <= (i_reg * k + b - (k - a) + nk_reg) % nk_reg;\n                        2'd3: l_reg <= (i_reg * k - b - (k - a) + 2*nk_reg) % nk_reg;\n                        default: l_reg <= 12'd0;\n                    endcase\n                    state <= COMPUTE_GCD;\n                end\n\n                COMPUTE_GCD: begin\n                    if (l_reg == 12'd0) begin\n                        gcd_result_reg <= nk_reg;\n                        state <= COMPUTE_STOPS;\n                    end else begin\n                        gcd_start <= 1'b1;\n                        if (gcd_done_flag) begin\n                            gcd_start <= 1'b0;\n                            state <= COMPUTE_STOPS;\n                        end\n                    end\n                end\n\n                COMPUTE_STOPS: begin\n                    stops_temp <= nk_reg / gcd_result;\n                    state <= UPDATE_MIN_MAX;\n                end\n\n                UPDATE_MIN_MAX: begin\n                    if (stops_temp < min_reg) min_reg <= stops_temp;\n                    if (stops_temp > max_reg) max_reg <= stops_temp;\n                    state <= NEXT_COMBO;\n                end\n\n                NEXT_COMBO: begin\n                    if (combo_reg < 2'd3) begin\n                        combo_reg <= combo_reg + 2'd1;\n                        state <= CALC_L;\n                    end else begin\n                        combo_reg <= 2'd0;\n                        state <= NEXT_I;\n                    end\n                end\n\n                NEXT_I: begin\n                    if (i_reg < (n - 5'd1)) begin\n                        i_reg <= i_reg + 5'd1;\n                        state <= CALC_L;\n                    end else begin\n                        state <= DONE_STATE;\n                    end\n                end\n\n                DONE_STATE: begin\n                    min_stops <= min_reg;\n                    max_stops <= max_reg;\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n\n                default: state <= IDLE;\n            endcase\n        end\n    end\n\nendmodule